package com.travbook.cabs.domain.model;
import com.travbook.shared.domain.*;
import java.time.*;
import java.util.*;
public final class Cab{
 private Cab(){}
 public enum Type{AIRPORT,LOCAL,OUTSTATION_ONE_WAY,OUTSTATION_ROUND_TRIP}public enum Place{DELHI_AIRPORT,DELHI_CENTRE,JAIPUR_CENTRE,AGRA_CENTRE,MUMBAI_AIRPORT,MUMBAI_CENTRE,PUNE_CENTRE,GOA_AIRPORT,GOA_CENTRE}public enum Category{HATCHBACK,SEDAN,SUV}public enum CategoryFilter{ALL,HATCHBACK,SEDAN,SUV}public enum Sort{PRICE,CAPACITY}
 public record Criteria(Type type,Place pickup,Place dropoff,LocalDate date,String time,LocalDate returnDate,String returnTime,int passengers,int luggage,int hours){
  public Criteria{if(type==null||pickup==null||dropoff==null||date==null||time==null||!time.matches("([01][0-9]|2[0-3]):[0-5][0-9]")||passengers<1||passengers>6||luggage<0||luggage>6)throw invalid("Choose valid pickup, time, passengers and luggage.");if(type==Type.LOCAL){if(pickup!=dropoff||!Set.of(4,8,12).contains(hours))throw invalid("Local rentals use the same pickup/drop area and a 4, 8 or 12 hour bundle.");}else if(pickup==dropoff||hours!=0)throw invalid("Choose different locations; rental hours apply only to local cabs.");if(type==Type.AIRPORT&&(!(pickup.name().endsWith("AIRPORT")||dropoff.name().endsWith("AIRPORT"))||!city(pickup).equals(city(dropoff))))throw invalid("Airport transfer must connect an airport and a different location in its city.");if(type==Type.OUTSTATION_ONE_WAY||type==Type.OUTSTATION_ROUND_TRIP)if(city(pickup).equals(city(dropoff)))throw invalid("Outstation trips require two different cities.");if(type==Type.OUTSTATION_ROUND_TRIP){if(returnDate==null||returnTime==null||!returnTime.matches("([01][0-9]|2[0-3]):[0-5][0-9]")||!at(returnDate,returnTime).isAfter(at(date,time).plusSeconds(7200))||returnDate.isAfter(date.plusDays(7)))throw invalid("Choose a return more than two hours after pickup, within seven days.");}else if(returnDate!=null||returnTime!=null)throw invalid("Return date/time applies only to outstation round trips.");}
  public void valid(Clock clock){if(!pickupAt().isAfter(clock.instant().plusSeconds(7200))||date.isAfter(LocalDate.now(clock.withZone(ZoneId.of("Asia/Kolkata"))).plusDays(90)))throw invalid("Schedule pickup more than two hours ahead and within 90 days.");}
  public Instant pickupAt(){return at(date,time);}public Instant returnAt(){return returnDate==null?null:at(returnDate,returnTime);}
 }
 public static String city(Place p){return p.name().substring(0,p.name().indexOf('_'));}private static Instant at(LocalDate d,String t){return d.atTime(LocalTime.parse(t)).atZone(ZoneId.of("Asia/Kolkata")).toInstant();}private static DomainFailure invalid(String message){return new DomainFailure(DomainFailure.Code.VALIDATION_FAILED,message);}
 public record Offer(UUID id,String supplier,Category category,int passengerCapacity,int luggageCapacity,int estimatedKm,int includedKm,int includedHours,Instant pickupAt,Instant returnAt,String timezone,TravelMoney baseFare,TravelMoney taxes,TravelMoney fees,TravelMoney total,TravelMoney extraKm,TravelMoney extraHour,List<String> inclusions,List<String> exclusions,String cancellationPolicy,String assumptions){public Offer{inclusions=List.copyOf(inclusions);exclusions=List.copyOf(exclusions);if(baseFare.decimal().add(taxes.decimal()).add(fees.decimal()).compareTo(total.decimal())!=0)throw new IllegalArgumentException("Inconsistent cab price");}}
 public record Inventory(List<Offer> offers,List<SupplierCoverage> coverage){}
 public record Snapshot(UUID id,Criteria criteria,List<Offer> offers,List<SupplierCoverage> coverage,Instant createdAt,Instant expiresAt,String mode) implements ObservedSnapshot{public Snapshot{offers=List.copyOf(offers);coverage=List.copyOf(coverage);if(!"MOCK".equals(mode)||!expiresAt.isAfter(createdAt))throw new IllegalArgumentException("Invalid cab snapshot");}public void fresh(Instant now){if(!expiresAt.isAfter(now))throw new DomainFailure(DomainFailure.Code.SEARCH_EXPIRED,"This cab search expired; search again.");}public Offer offer(UUID id){return offers.stream().filter(o->o.id().equals(id)).findFirst().orElseThrow(()->new DomainFailure(DomainFailure.Code.NOT_FOUND,"Cab offer was not returned by this search."));}}
 public record Page(UUID id,Criteria criteria,List<Offer> items,List<SupplierCoverage> coverage,Instant createdAt,Instant expiresAt,String mode,int total){}
 public record Detail(UUID searchId,Criteria criteria,Offer offer,Instant observedAt,Instant expiresAt,String mode){}
 public record FareCheck(Offer offer,TravelMoney previousTotal,boolean changed,Instant checkedAt,Instant validUntil,String mode){}
}
